// src/utils/pdfGenerator.ts
function downloadPDF(doc3, fileName) {
  const cleanFileName = fileName.endsWith(".pdf") ? fileName : `${fileName}.pdf`;
  try {
    const blob = doc3.output("blob");
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = cleanFileName;
    link.target = "_self";
    link.style.display = "none";
    document.body.appendChild(link);
    link.click();
    setTimeout(() => {
      if (document.body.contains(link)) {
        document.body.removeChild(link);
      }
      URL.revokeObjectURL(url);
    }, 2e3);
  } catch (err) {
    console.warn("downloadPDF blob anchor failed, falling back to doc.save:", err);
    try {
      doc3.save(cleanFileName);
    } catch (saveErr) {
      console.error("doc.save failed:", saveErr);
      const dataUri = doc3.output("datauristring");
      window.open(dataUri, "_blank");
    }
  }
}
function escapeHTML(str) {
  if (!str) return "";
  return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}
function openPrintWindow(html, title) {
  const enhancedHtml = html.includes('id="rbc-print-bar"') ? html : html.replace(
    "<body>",
    '<body><div id="rbc-print-bar" style="position:sticky;top:0;z-index:9999;background:#0f172a;color:white;padding:12px 20px;display:flex;justify-content:space-between;align-items:center;box-shadow:0 4px 6px -1px rgba(0,0,0,0.1);margin:-20px -20px 20px -20px;"><div style="font-size:13px;font-weight:600;">RBC Transformaci\xF3n \u2022 Documento Oficial</div><button onclick="window.print()" style="background:white;color:#0f172a;border:none;padding:8px 16px;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;">\u{1F5A8}\uFE0F Imprimir / Guardar como PDF</button></div><script>setTimeout(function(){try{window.focus();window.print();}catch(e){}},500);</script>'
  );
  let printWindow = null;
  try {
    printWindow = window.open("", "_blank");
  } catch {
    printWindow = null;
  }
  if (printWindow) {
    printWindow.document.open();
    printWindow.document.write(enhancedHtml);
    printWindow.document.close();
  } else {
    try {
      const iframe = document.createElement("iframe");
      iframe.style.position = "fixed";
      iframe.style.right = "0";
      iframe.style.bottom = "0";
      iframe.style.width = "0";
      iframe.style.height = "0";
      iframe.style.border = "none";
      document.body.appendChild(iframe);
      const doc3 = iframe.contentWindow?.document;
      if (doc3) {
        doc3.open();
        doc3.write(enhancedHtml);
        doc3.close();
        setTimeout(() => {
          try {
            iframe.contentWindow?.focus();
            iframe.contentWindow?.print();
          } catch (e) {
            console.warn("Iframe print failed:", e);
          }
          setTimeout(() => {
            if (document.body.contains(iframe)) {
              document.body.removeChild(iframe);
            }
          }, 6e4);
        }, 500);
        return;
      }
    } catch (iframeErr) {
      console.warn("Hidden iframe print failed:", iframeErr);
    }
  }
}
